import os
import pytest
from envcfg import load_config, EnvCfgError


def test_defaults_only():
    cfg = load_config({"a": 1, "b": 2})
    assert cfg == {"a": 1, "b": 2}


def test_toml_overrides_defaults():
    cfg = load_config({"a": 1, "b": 2}, toml_path="test.toml")
    assert cfg["a"] == 1
    assert cfg["b"] == 2
    assert cfg["c"] == 3


def test_env_overrides_toml():
    cfg = load_config({}, toml_path="test.toml", env={"APP__C": "999"})
    assert cfg["c"] == 999


def test_env_overrides_defaults():
    cfg = load_config({"a": 1}, env={"APP__A": "2"})
    assert cfg["a"] == 2


def test_nested_toml():
    cfg = load_config({}, toml_path="nested.toml")
    assert cfg["server"]["port"] == 8080


def test_nested_env():
    cfg = load_config({}, env={"APP__SERVER__PORT": "9000"})
    assert cfg["server"]["port"] == 9000


def test_nested_env_overrides_toml():
    cfg = load_config({}, toml_path="nested.toml", env={"APP__SERVER__PORT": "9000"})
    assert cfg["server"]["port"] == 9000


def test_int_coercion():
    cfg = load_config({"x": 10}, env={"APP__X": "20"})
    assert cfg["x"] == 20


def test_float_coercion():
    cfg = load_config({"y": 1.5}, env={"APP__Y": "2.5"})
    assert cfg["y"] == 2.5


def test_bool_coercion_yes():
    cfg = load_config({"z": True}, env={"APP__Z": "yes"})
    assert cfg["z"] is True


def test_bool_coercion_no():
    cfg = load_config({"z": False}, env={"APP__Z": "no"})
    assert cfg["z"] is False


def test_bool_coercion_one():
    cfg = load_config({"z": True}, env={"APP__Z": "1"})
    assert cfg["z"] is True


def test_bool_coercion_zero():
    cfg = load_config({"z": False}, env={"APP__Z": "0"})
    assert cfg["z"] is False


def test_str_coercion():
    cfg = load_config({"msg": "hello"}, env={"APP__MSG": "world"})
    assert cfg["msg"] == "world"


def test_missing_toml_not_error():
    cfg = load_config({"a": 1}, toml_path="nonexistent.toml")
    assert cfg["a"] == 1


